.neon-demo {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 24px;
  padding: 20px;
}

.neon-text {
  font-size: clamp\(2rem, 5vw, 3.5rem\);
  font-weight: 700;
  color: #fff;
  text-transform: uppercase;
  letter-spacing: 0.15em;
  animation: neonGlow 3s ease-in-out infinite;

  &.delay-1 { animation-delay: -1s; }
  &.delay-2 { animation-delay: -2s; }
}

@keyframes neonGlow {
  0% {
    text-shadow:
      0 0 10px #ff00ff, 0 0 20px #ff00ff, 0 0 40px #ff00ff,
      0 0 60px #ff00ff, 2px 2px 70px #ff00ff;
    color: #ffaaff;
  }
  25% {
    text-shadow:
      0 0 10px #00ffff, 0 0 20px #00ffff, 0 0 40px #00ffff,
      0 0 60px #00ffff, -2px 0 70px #00ffff;
    color: #aaffff;
  }
  50% {
    text-shadow:
      0 0 10px #39ff14, 0 0 20px #39ff14, 0 0 40px #39ff14,
      0 0 60px #39ff14, 0 -2px 70px #39ff14;
    color: #aaffaa;
