.cards-wrapper {
  display: flex;
  gap: 20px;
  flex-wrap: wrap;
  justify-content: center;
}

.hover-card {
  width: 180px;
  height: 220px;
  border-radius: 16px;
  cursor: pointer;
  transition: transform 0.3s ease, filter 0.3s ease;
  position: relative;
  overflow: hidden;
  flex-shrink: 0;

  &.card-red   { background: linear-gradient\(135deg, #ff4444, #cc0000\); }
  &.card-blue  { background: linear-gradient\(135deg, #4488ff, #0044cc\); }
  &.card-green { background: linear-gradient\(135deg, #44dd88, #009944\); }
}

.cards-wrapper:has\(.hover-card:hover\) .hover-card:not\(:hover\) {
  transform: scale\(0.9\);
  filter: blur\(3px\) brightness\(0.6\);
}

.cards-wrapper:has\(.hover-card:hover\) .hover-card:hover {
  transform: scale\(1.08\);
  box-shadow: 0 20px 60px rgba\(0,0,0,0.5\);
}

